def transform(grid):
    """Move 4s one cell toward the horizontal 2 barrier. A 4 that lands
    immediately beside the barrier also casts diagonal rays back across its side."""
    h, w = len(grid), len(grid[0])
    wall = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if wall is None:
        return [row[:] for row in grid]
    out = [[0] * w for _ in range(h)]
    out[wall] = grid[wall][:]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 4:
                continue
            if r < wall:
                nr = r + 1
                if nr < wall:
                    out[nr][c] = 4
                    if nr == wall - 1:
                        for d in range(1, max(h, w)):
                            rr = nr - d
                            if rr < 0:
                                break
                            for cc in (c - d, c + d):
                                if 0 <= cc < w:
                                    out[rr][cc] = 4
            else:
                # Markers on the far side of the divider remain fixed.
                out[r][c] = 4
    return out
